import { vi, test, expect } from 'vitest';

test('charges with retry', async () => {
  // ❌ over-mock: always succeeds, never checks the amount
  const gateway = { charge: vi.fn().mockResolvedValue({ status: 'ok' }) };
  // ❌ retryWithBackoff sleeps 1s then 2s for REAL — test takes ~3s
  const receipt = await checkout(order, { gateway });
  expect(gateway.charge).toHaveBeenCalled();
});

model.en:
Use a fake that records real amounts, assert on the receipt, and drive the backoff with fake timers:

import { vi, test, expect } from 'vitest';

function makeFakeGateway() {
  const charges = [];
  return {
    charges,
    async charge({ cents }) {
      if (!Number.isInteger(cents) || cents <= 0) throw new Error('bad amount');
      charges.push(cents);
      return { status: 'ok', cents };
    },
  };
}

test('charges the order in cents, with retry', async () => {
  vi.useFakeTimers();
  const gateway = makeFakeGateway();
  const p = checkout(order, { gateway });        // schedules backoff internally
  await vi.advanceTimersByTimeAsync(3000);        // advance clock AND flush microtasks
  const receipt = await p;
  expect(receipt.chargedCents).toBe(4900);        // OUTCOME, not a call count — catches dollars-vs-cents
  expect(gateway.charges).toEqual([4900]);        // exactly one real charge of the right amount
  vi.useRealTimers();
});

Why it's right: the fake validates and records the amount, so a $4900-vs-$49 bug fails the test; the assertion is on the receipt/recorded charge (outcome), not on toHaveBeenCalled (interaction); and advanceTimersByTimeAsync moves virtual time AND drains microtasks, so the ~3s of real backoff runs in milliseconds.

model.ru:
Используй fake, который записывает реальные суммы, проверяй чек и гони бэкофф фейковыми таймерами:

import { vi, test, expect } from 'vitest';

function makeFakeGateway() {
  const charges = [];
  return {
    charges,
    async charge({ cents }) {
      if (!Number.isInteger(cents) || cents <= 0) throw new Error('bad amount');
      charges.push(cents);
      return { status: 'ok', cents };
    },
  };
}

test('charges the order in cents, with retry', async () => {
  vi.useFakeTimers();
  const gateway = makeFakeGateway();
  const p = checkout(order, { gateway });        // внутри планирует бэкофф
  await vi.advanceTimersByTimeAsync(3000);        // двигает часы И опустошает микротаски
  const receipt = await p;
  expect(receipt.chargedCents).toBe(4900);        // ИТОГ, а не число вызовов — ловит доллары-vs-центы
  expect(gateway.charges).toEqual([4900]);        // ровно одно реальное списание верной суммы
  vi.useRealTimers();
});

Почему верно: fake валидирует и записывает сумму, так что баг $4900-vs-$49 валит тест; проверка на чеке/записанном списании (итог), а не на toHaveBeenCalled (взаимодействие); и advanceTimersByTimeAsync двигает виртуальное время И сливает микротаски, так что ~3с реального бэкоффа бегут миллисекунды.
